use bessel::{itstruve0, struve};

#[test]
fn integrated_struve_matches_independent_high_precision_hypergeometric() {
    // Input and reference tables are separately generated by pinned mpmath;
    // the reference identity uses 2F3, independent of the Rust quadrature
    // and asymptotic implementations.
    let inputs = include_str!("scipy/itstruve0_large_inputs.csv");
    let expected = include_str!("fixtures/itstruve0_large_expected.csv");
    let mut results = expected.lines().skip(1);
    let mut count = 0;
    for entry in inputs.lines().skip(1) {
        let x: f64 = entry.parse().unwrap();
        let reference: f64 = results
            .next()
            .expect("missing expected row")
            .parse()
            .unwrap();
        let actual = itstruve0(x);
        let relative_tolerance = if x > 512.0 { 3e-15 } else { 3e-14 };
        assert!(
            (actual - reference).abs() <= relative_tolerance * reference.abs(),
            "itstruve0({x:e}) got {actual:.17e}, expected {reference:.17e}, relative error {:e}",
            (actual - reference).abs() / reference.abs()
        );
        // H0 is odd; its integral from zero is even for every finite input.
        assert_eq!(itstruve0(-x), actual, "evenness at {x:e}");
        count += 1;
    }
    assert_eq!(count, 21);
    assert!(results.next().is_none(), "unexpected extra reference row");
}

#[test]
fn integrated_struve_infinite_and_nan_limits() {
    assert_eq!(itstruve0(f64::INFINITY), f64::INFINITY);
    assert_eq!(itstruve0(f64::NEG_INFINITY), f64::INFINITY);
    assert!(itstruve0(f64::NAN).is_nan());
    assert_eq!(itstruve0(-0.0), 0.0);
    assert!(itstruve0(-0.0).is_sign_positive());
    assert!(itstruve0(f64::MAX).is_finite());
}

#[test]
fn large_argument_integral_derivative_matches_struve_h0() {
    // Fundamental theorem of calculus, including the continuation boundary.
    for x in [513.0, 600.0, 750.0, 1000.0] {
        let h = 0.001;
        let forward = x + h;
        let backward = x - h;
        let derivative = (itstruve0(forward) - itstruve0(backward)) / (forward - backward);
        let expected = struve(0.0, x);
        assert!(
            (derivative - expected).abs() < 5e-7 * expected.abs(),
            "d/dx itstruve0 at {x} got {derivative}, H0={expected}"
        );
    }
}
